'use strict';const eok=n=>n==null?'—':(Number(n)/10000).toLocaleString('ko-KR',{maximumFractionDigits:2})+'억';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function load(){const [m,k]=await Promise.all([fetch('buy_watchlist_market.json?v='+Date.now(),{cache:'no-store'}).then(r=>r.json()),fetch('buy_watchlist_master.json?v='+Date.now(),{cache:'no-store'}).then(r=>r.json())]);const market=m.items||[], master=k.items||[];document.querySelector('#updated').textContent='KB '+new Date(k.kb_collected_at||Date.now()).toLocaleDateString('ko-KR')+' · MARKET '+new Date(m.collected_at||Date.now()).toLocaleDateString('ko-KR');document.querySelector('#marketDate').textContent='MARKET '+new Date(m.collected_at||Date.now()).toLocaleDateString('ko-KR');const kb=new Map(master.map(x=>[Number(x.complex_id),Math.min(...(x.types||[]).map(t=>Number(t.general_price_manwon)).filter(Boolean))]));const under=[...kb.values()].filter(v=>v<=150000).length,near=[...kb.values()].filter(v=>v>150000&&v<=170000).length,inc=market.filter(x=>Number(x.sale_listing_week_delta)>0).length,dec=market.filter(x=>Number(x.sale_listing_week_delta)<0).length,trades=market.filter(x=>x.recent_trade_manwon!=null).length;document.querySelector('#myMarket').innerHTML=[['관심단지',master.length,'개'],['KB ≤15억',under,'개'],['15~17억',near,'개'],['매물 증가',inc,'개'],['최근거래 확보',trades,'개']].map(x=>'<div><span>'+x[0]+'</span><b>'+x[1]+'</b><small>'+x[2]+'</small></div>').join('');const boundary=[...master].map(x=>({name:x.user_name||x.kb_name,p:kb.get(Number(x.complex_id))})).filter(x=>x.p&&x.p>=130000&&x.p<=170000).sort((a,b)=>Math.abs(a.p-150000)-Math.abs(b.p-150000)).slice(0,7);document.querySelector('#boundary').innerHTML=boundary.length?boundary.map(x=>'<div class="row"><span>'+esc(x.name)+'</span><b class="'+(x.p<=150000?'up':'')+'">'+eok(x.p)+'</b></div>').join(''):'<small>13~17억 구간 데이터 없음</small>';const radar=[...market].filter(x=>x.sale_listing_week_delta!=null).sort((a,b)=>Math.abs(Number(b.sale_listing_week_delta))-Math.abs(Number(a.sale_listing_week_delta))).slice(0,7);document.querySelector('#radar').innerHTML=radar.map(x=>'<div class="radar-row"><span>'+esc(x.name)+'</span><b class="'+(x.sale_listing_week_delta>0?'down':x.sale_listing_week_delta<0?'up':'')+'">'+(x.sale_listing_week_delta>0?'+':'')+x.sale_listing_week_delta+'건</b></div>').join('');const rows=[...market].sort((a,b)=>Math.abs(Number(b.sale_listing_week_delta||0))-Math.abs(Number(a.sale_listing_week_delta||0)));document.querySelector('#body').innerHTML=rows.map(x=>'<tr><td><b>'+esc(x.name)+'</b><small>'+esc(x.market_scope||'')+'</small></td><td>'+eok(kb.get(Number(x.complex_id)))+'</td><td>'+eok(x.avg_ask_manwon)+'</td><td>'+eok(x.recent_trade_manwon)+'<small>'+esc(x.recent_trade_date||'')+'</small></td><td>'+Number(x.sale_listing_count||0).toLocaleString()+'건</td><td class="'+(x.sale_listing_week_delta>0?'down':x.sale_listing_week_delta<0?'up':'')+'">'+(x.sale_listing_week_delta>0?'+':'')+Number(x.sale_listing_week_delta||0)+'건</td></tr>').join('')}load().catch(e=>{document.querySelector('#updated').textContent='DATA ERROR';console.error(e)});